package com.hickorydocs.simple
import org.junit.Test
import org.junit.Assert.*
import org.json.JSONObject
import org.json.JSONArray
class SnippetDerivedTest {
 private fun vectors():JSONObject {val root=generateSequence(java.io.File(System.getProperty("user.dir")).absoluteFile){it.parentFile}.first{it.resolve("apps/simple-contract/snippet-derived-cases.json").isFile};return JSONObject(root.resolve("apps/simple-contract/snippet-derived-cases.json").readText())}
 private fun fields(values:JSONArray,programs:JSONObject)=(0 until values.length()).map{index->val value=values.getJSONObject(index);val choices=value.getJSONArray("choices");SnippetField(value.getInt("index"),value.getInt("from"),value.getInt("to"),(0 until choices.length()).map{choices.getString(it)},if(value.isNull("id"))null else value.getInt("id"),if(value.isNull("parent"))null else value.getInt("parent"),if(value.has("transform"))readSnippetTransform(programs.getJSONObject(value.getString("transform")))else null)}
 @Test fun sharedComputedEditsScopesAndBoundaries(){val value=vectors();val programs=value.getJSONObject("programs");val cases=value.getJSONArray("cases");for(index in 0 until cases.length()){val row=cases.getJSONObject(index);val name=row.getString("name");var source=row.getString("source");var session=beginSnippet(source,fields(row.getJSONArray("fields"),programs));if(row.optBoolean("invalidBegin")){assertNull(name,session);continue};assertNotNull(name,session);if(row.has("current"))assertEquals(name,row.getInt("current"),session!!.current)
  val steps=row.getJSONArray("steps");for(at in 0 until steps.length()){val step=steps.getJSONObject(at);val current=session!!;val action=step.getString("action");if(action=="select"){val id=step.getInt("id");val group=step.getInt("index");assertTrue(name,current.fields.any{it.id==id&&it.transform==null&&it.index==group});session=current.copy(active=group,current=id);continue};val before=current.copy(fields=current.fields.map{it.copy(choices=it.choices.toList())},scopes=current.scopes.toList());val input=step.optString("currentSource",source);val from=step.getInt("from");val to=step.getInt("to");val selected:CompletionSelection;val next:SnippetSession?
   if(action in listOf("edit","complete","nest")){val additions=step.optJSONArray("additional")?:JSONArray();val additional=(0 until additions.length()).map{val edit=additions.getJSONObject(it);SourceReplacement(edit.getInt("from"),edit.getInt("to"),edit.getString("text"))};val primary=SourceReplacement(from,to,step.optString("text",""));val result=when(action){"nest"->nestSnippet(current,input,primary,additional,fields(step.optJSONArray("inner")?:JSONArray(),programs));"complete"->completeSnippet(current,input,primary,additional);else->editSnippet(current,input,from,to,primary.text)};assertEquals(name,before,current);if(step.optBoolean("refuse")){assertNull(name,result);continue};assertNotNull(name,result);assertEquals(name,step.getString("after"),result!!.session.source);source=result.session.source;selected=result.selection;next=result.session
   }else{val result=advanceSnippet(current,input,from,to,if(action=="next")1 else -1);assertEquals(name,before,current);if(step.optBoolean("refuse")){assertNull(name,result);continue};assertNotNull(name,result);selected=result!!.selection;next=result.session}
   val selection=step.getJSONObject("selection");assertEquals(name,selection.getInt("from"),selected.from);assertEquals(name,selection.getInt("to"),selected.to);session=next;if(step.has("active"))assertEquals(name,if(step.isNull("active"))null else step.getInt("active"),session?.active);if(step.has("depth"))assertEquals(name,step.getInt("depth"),session?.scopes?.size?:0);if(step.has("indices")){val indices=step.getJSONArray("indices");assertEquals(name,(0 until indices.length()).map{indices.getInt(it)},session?.fields?.map{it.index})}
  }
 }}
 @Test fun expansionV2FenceKeepsEqualInitialComputedTextFromLegacyClients(){val syntax="${'$'}{1/(.*)/${'$'}{1:/upcase}/} ${'$'}{1:FOO}${'$'}0";val raw=JSONObject().put("version",1).put("syntax",syntax).put("text","FOO FOO").put("fields",JSONArray().put(JSONObject().put("id",0).put("parent",JSONObject.NULL).put("index",1).put("from",0).put("to",3).put("choices",JSONArray()).put("transform",vectors().getJSONObject("programs").getJSONObject("upper"))).put(JSONObject().put("id",1).put("parent",JSONObject.NULL).put("index",1).put("from",4).put("to",7).put("choices",JSONArray())).put(JSONObject().put("id",2).put("parent",JSONObject.NULL).put("index",0).put("from",7).put("to",7).put("choices",JSONArray())))
  fun item()=JSONObject().put("label","guarded").put("insertText",syntax).put("insertTextFormat",2).put("data",JSONObject().put("hickory_snippet",raw))
  assertTrue(runCatching{completionExpansion(item())}.isFailure);raw.put("version",2);val expanded=completionExpansion(item())!!;assertEquals(4,expanded.selection!!.from);assertEquals(7,expanded.selection.to);assertNotNull(expanded.fields[0].transform);raw.put("text","fOo FOO");assertTrue(runCatching{completionExpansion(item())}.isFailure)
 }
}
